def holdout(root):
    require_local_source(root)
    import research.campaigns.hp.dense_gen as DG, research.campaigns.hp.dgp_paths as dgp_paths
    fr = json.load(open(os.path.join(RD, 'FREEZE.json'))); head = git(root, 'rev-parse', 'HEAD'); assert head == fr['code']['commit'], 'holdout must be generated at the frozen commit (%s != %s)' % (head[:9], fr['code']['commit'][:9])
    fm = DG.generate('eval6', os.path.join(RD, 'inputs_fresh')); om = DG.generate('oracle6', os.path.join(RD, 'oracle', 'inputs_fresh'))                    # the ONLY generations of this round (after the second freeze)
    def mk(m, panel, exposure, extra=None): return dict(dict(name=m['name'], panel=panel, exposure=exposure, topology=m['topology'], n=m['n'], card=m['card'], scale=m['scale'], model=m['model'], model_sha256=m['model_sha256'], evid_sha256=m['evid_sha256'], K=m['K'], edges=m['edges'], cycle_rank=m['cycle_rank'], degree=m['degree'], graph_attempts_rejected=m['graph_attempts_rejected'], exact_profile_reduction=m['exact_profile_reduction'], dynamic_range=m['dynamic_range'], seed=m['seed'], seed_record=m.get('seed_record'), tag=m['tag']), **(extra or {}))
    fresh = verify([mk(m, 'fresh_8', 'fresh (DGP6/EVAL6/; generated after the second freeze)') for m in fm]); fresh_oracle = verify([mk(m, 'oracle_fresh_4', 'fresh oracle (DGP6/ORACLE6/; generated after the second freeze; oracle only)', dict(fine_states=m['card'] ** m['n'])) for m in om])
    for t in fresh: t['name_generated'] = t['name']; t['name'] = t['name'] + '__eval6'
    for t in fresh_oracle: t['name_generated'] = t['name']; t['name'] = t['name'] + '__oracle6'
    oracle28 = verify([dict(t, exposure='exposed to the oracle (DGP2 / DGP4 / DGP5 oracle inputs; bytes verified)') for t in json.load(open(os.path.join(DGP5, 'ORACLE_MANIFEST.json')))['tasks']]); assert len(oracle28) == 28
    main5 = json.load(open(os.path.join(DGP5, 'MAIN_MANIFEST.json')))['tasks']; exposed60 = verify([dict(t, exposure='exposed (the 60 DGP5 main inputs: 52 DGP4 + 8 EVAL5 as __eval5; original bytes)', panel_dgp5=t.get('panel'), panel='exposed_60') for t in main5]); assert len(exposed60) == 60 and len({t['name'] for t in exposed60}) == 60
    pres18 = verify([dict(t, exposure='exposed (USR1 / DGP1 preservation)') for t in json.load(open(os.path.join(DGP1, 'PRESERVATION_18_MANIFEST.json')))['tasks']]); pres13 = verify([dict(t, exposure='exposed (accepted preservation panel)') for t in json.load(open(os.path.join(DGP1, 'PRESERVATION_13_MANIFEST.json')))['tasks']])
    byname = {t['name']: t for t in exposed60 + pres18 + pres13}; diag = [byname[n] for n in DIAG_NAMES]; oldpol = [byname[n] for n in OLDPOL_NAMES]; assert len(diag) == 8 and len(oldpol) == 8
    main = exposed60 + fresh; assert len(main) == 68 and len({(t['model_sha256'], t['evid_sha256']) for t in main}) == 68
    o_by = {t['name']: t for t in oracle28 + fresh_oracle}; prio5 = PRIORITY_EXPOSED + PRIORITY_FRESH; rest = sorted({n for n in DGP5_ANCHORS + FRESH_ER if n not in prio5}, key=lambda n: o_by[n]['model_sha256']); assert all(n in o_by for n in prio5 + rest), [n for n in prio5 + rest if n not in o_by]
    for name, tasks in (('ORACLE_MANIFEST', oracle28 + fresh_oracle), ('FRESH_MANIFEST', fresh), ('MAIN_MANIFEST', main), ('PRESERVATION_18_MANIFEST', pres18), ('PRESERVATION_13_MANIFEST', pres13), ('DIAG_MANIFEST', diag), ('OLDPOL_MANIFEST', oldpol)): json.dump(dict(tasks=tasks, code_commit=head, freeze_sha256=sha(os.path.join(RD, 'FREEZE.json'))), open(os.path.join(RD, name + '.json'), 'w'), indent=1)
    allm = dict(experiment='DGP6_GLOBAL_CONSTRUCTION', utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), code_commit=head, freeze_sha256=sha(os.path.join(RD, 'FREEZE.json')), generated_manifests=[os.path.join(RD, 'inputs_fresh', 'GENERATED_MANIFEST.json'), os.path.join(RD, 'oracle', 'inputs_fresh', 'GENERATED_MANIFEST.json')],
                panels=dict(oracle_28=oracle28, oracle_fresh_4=fresh_oracle, oracle_32=oracle28 + fresh_oracle, fresh_8=fresh, exposed_60=exposed60, main_68=main, preservation_18=pres18, preservation_13=pres13, diag_8=[t['name'] for t in diag], oldpol_8=[t['name'] for t in oldpol], replay_anchors=dict(priority_5=prio5, exposed_hard_n8_cliques=PRIORITY_EXPOSED, fresh_cliques=PRIORITY_FRESH, remaining_hash_order=rest, dgp5_anchors_11=DGP5_ANCHORS, fresh_er=FRESH_ER)),
                exposure_labels=dict(fresh='generated after the second freeze (DGP6/EVAL6/); production arms', fresh_oracle='generated after the second freeze (DGP6/ORACLE6/); oracle only', exposed='bytes identical to DGP1-DGP5 / USR1 / accepted-panel inputs (sha256 verified now)', oracle='DGP2 / DGP4 / DGP5 oracle inputs (exposed to oracle calculations only; never production arms)'))
    json.dump(allm, open(os.path.join(RD, 'MODEL_MANIFEST.json'), 'w'), indent=1); print('oracle', len(oracle28), '+', len(fresh_oracle), 'fresh', len(fresh), 'exposed', len(exposed60), 'main', len(main), 'pres', len(pres18), len(pres13), 'diag', len(diag), 'oldpol', len(oldpol)); print('fresh seeds', [(t['name'], t['seed'], (t.get('seed_record') or {}).get('canonical_json')) for t in fresh]); print('fresh oracle', [(t['name'], t['seed'], t['exact_profile_reduction'].get('variables_reduced')) for t in fresh_oracle]); print('replay priority', prio5, 'then', rest)

